<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Download, Refresh, Search, Setting } from '@element-plus/icons-vue'
import { ElButton, ElDatePicker, ElForm, ElFormItem, ElInput, ElMessage, ElOption, ElPagination, ElSelect, ElTable, ElTableColumn, ElTag } from 'element-plus'
import TransmissionSettingsDialog from '../components/task-plan/TransmissionSettingsDialog.vue'; import PageHeader from '../components/shell/PageHeader.vue'; import PrototypeStatePanel from '../components/shell/PrototypeStatePanel.vue'
import { transmissionRecords } from '../mocks/taskPlans';import type { PrototypeState } from '../types/prototype'
const params=new URLSearchParams(location.search);const state=(params.get('state')||'normal') as PrototypeState;const settings=ref(false);const currentPage=ref(1);const pageSize=ref(30);const filters=reactive({planNo:'',range:[] as string[],status:''});const applied=ref({...filters,range:[] as string[]});const rows=computed(()=>transmissionRecords.filter(x=>(!applied.value.planNo||x.planNo.includes(applied.value.planNo))&&(!applied.value.status||x.status===applied.value.status)&&(!applied.value.range.length||(x.sentAt>=applied.value.range[0]&&x.sentAt<=applied.value.range[1]))));onMounted(()=>settings.value=params.get('dialog')==='settings');function query(){applied.value={...filters,range:[...filters.range]};ElMessage.success(`查询完成，共 ${rows.value.length} 条证据样例`)}function reset(){Object.assign(filters,{planNo:'',range:[],status:''});applied.value={...filters,range:[]};ElMessage.success('筛选条件已重置')}function exportRows(){ElMessage.success('发送记录导出已生成')}
</script>
<template><section class="requirement-page transmission-page"><PageHeader title="计划发送记录"/><PrototypeStatePanel v-if="state!=='normal'" :state="state" subject="计划发送记录"/><template v-else><div class="filter-panel compact-page-filter"><el-form class="filter-form"><el-form-item label="任务计划号"><el-input v-model="filters.planNo" placeholder="请输入"/></el-form-item><el-form-item class="date-field" label="发送时间"><el-date-picker v-model="filters.range" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间"/></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" placeholder="请选择" clearable><el-option label="发送成功" value="发送成功"/><el-option label="发送失败" value="发送失败"/></el-select></el-form-item></el-form><div class="filter-actions"><el-button type="primary" :icon="Search" @click="query">查询</el-button><el-button :icon="Refresh" @click="reset">重置</el-button><el-button :icon="Download" @click="exportRows">导出</el-button></div></div><div class="batch-actions"><el-button type="primary" plain :icon="Setting" @click="settings=true">计划发送设置</el-button><span>时间：北京时间（UTC+8）</span></div><div class="table-region"><el-table :data="rows" height="100%" class="requirement-table"><el-table-column prop="sequence" label="序号" width="70" align="center"/><el-table-column prop="planNo" label="计划编号" min-width="150"/><el-table-column prop="type" label="类型" min-width="100"/><el-table-column prop="timeliness" label="时效类型" min-width="110"/><el-table-column prop="sentAt" label="发送时间" min-width="180"/><el-table-column label="状态" width="110" align="center"><template #default="{row}"><el-tag :type="row.status==='发送成功'?'success':'danger'" effect="light">{{ row.status }}</el-tag></template></el-table-column><el-table-column prop="failureReason" label="发送失败原因" min-width="420" show-overflow-tooltip/></el-table></div><div class="pagination-bar"><el-pagination v-model:current-page="currentPage" v-model:page-size="pageSize" background layout="total, sizes, prev, pager, next, jumper" :total="602" :page-sizes="[10,30,50,100,200]"/></div></template><TransmissionSettingsDialog v-model:visible="settings"/></section></template>
